import React from "react";

const Filter = ({ filterData }) => {
  let filter
  return (
    <div>
      {filterData.map((data) => {
        return (
          <button  key = {data.id}>
            {data.title}
          </button>
        );
      })}
    </div>
  );
};

export default Filter;
